    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # (row offset, col offset, color) for the three observed L orientations.
    colors = { (0,0): 2, (0,1): 4, (1,0): 3, (1,1): 5 }
    # Exact cover by all 2x2 squares / 3-cell L tiles, using a deterministic
    # search. Prefer squares, then Ls; unseen orientation is provisionally 5.
    candidates = []
    for r in range(h-1):
        for c in range(w-1):
            box = {(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
            if box <= cells:
                candidates.append((box, 1, (r,c), 0))
            for missing in box:
                shape = box - {missing}
                if shape <= cells:
                    # color keyed by missing corner offset
                    key = (missing[0]-r, missing[1]-c)
                    candidates.append((shape, colors[key], (r,c), 1))
    # Solve exact cover; square-first tie-break mirrors the demonstrated tiling.
    def search(rem, chosen):
        if not rem:
            return chosen
        p = min(rem)
        opts = [x for x in candidates if p in x[0] and x[0] <= rem]
        opts.sort(key=lambda x: (x[3], x[2], x[1]))
        for x in opts:
            ans = search(rem - x[0], chosen + [x])
            if ans is not None:
                return ans
